def dihedral(cells):
    mr=min(r for r,c in cells);mc=min(c for r,c in cells)
    pts=[(r-mr,c-mc) for r,c in cells]
    res=set()
    for k in range(4):
        for flip in (False,True):
            t=[(r,c) for r,c in pts]
            if flip: t=[(r,-c) for r,c in t]
            for _ in range(k): t=[(c,-r) for r,c in t]
            mr2=min(r for r,c in t);mc2=min(c for r,c in t)
            res.add(tuple(sorted((r-mr2,c-mc2) for r,c in t)))
    return frozenset(res)
